class Connector(BaseModel):
    """
    Connector declaration (PRD 12.1), one entry of config/connectors.yaml. Every action declares a risk tier and a gate type (FR-CON-06); write, send, share and delete actions are gated and deletes are always T3; an action with gate_type none is never T3 or irreversible.
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    id: ConnectorId
    name: PlainName
    """
    Island name in the world.
    """
    icon: IconName
    auth: Literal["oauth2", "platform", "none"]
    """
    oauth2: the user's own sign-in with PKCE; platform: a team-owned key; none.
    """
    scopes: ConnectorScopes
    capabilities: Annotated[list[ConnectorCapability], Field(min_length=1)]
    actions: Annotated[list[ConnectorAction], Field(min_length=1)]
    limits: ConnectorLimits
